import pandas as pd
from datetime import datetime
import re

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_indices = set(raw.index)

    # R1: MISSING_ID - payment_id is NULL or empty after TRIM
    r1_fail = raw["payment_id"].isna() | (raw["payment_id"].str.strip() == "")
    for idx in raw[r1_fail].index:
        rejects.append({"row_num": raw.loc[idx, "row_num"], "reject_reason": "MISSING_ID"})
        valid_indices.discard(idx)

    # R2: BAD_AMOUNT - must match legacy number pattern
    def is_legacy_number(s):
        if pd.isna(s):
            return False
        s = str(s).strip()
        # Pattern: optional +/-, one or more digits, optional .DD
        pattern = r'^[+-]?\d+(\.\d{1,2})?$'
        return bool(re.match(pattern, s))

    r2_fail = ~r1_fail & ~raw["amount_txt"].apply(is_legacy_number)
    for idx in raw[r2_fail].index:
        if idx in valid_indices:
            rejects.append({"row_num": raw.loc[idx, "row_num"], "reject_reason": "BAD_AMOUNT"})
            valid_indices.discard(idx)

    # R3: NON_POSITIVE - amount <= 0
    def parse_amount(s):
        if pd.isna(s):
            return None
        s = str(s).strip()
        try:
            return float(s)
        except:
            return None

    amounts = raw["amount_txt"].apply(parse_amount)
    r3_fail = ~r1_fail & ~r2_fail & (amounts <= 0)
    for idx in raw[r3_fail].index:
        if idx in valid_indices:
            rejects.append({"row_num": raw.loc[idx, "row_num"], "reject_reason": "NON_POSITIVE"})
            valid_indices.discard(idx)

    # R4: BAD_CURRENCY - must be USD, EUR, or GBP (case-insensitive)
    def is_valid_currency(s):
        if pd.isna(s):
            return False
        return str(s).strip().upper() in ["USD", "EUR", "GBP"]

    r4_fail = ~r1_fail & ~r2_fail & ~r3_fail & ~raw["currency"].apply(is_valid_currency)
    for idx in raw[r4_fail].index:
        if idx in valid_indices:
            rejects.append({"row_num": raw.loc[idx, "row_num"], "reject_reason": "BAD_CURRENCY"})
            valid_indices.discard(idx)

    # R5: BAD_DATE - must be YYYY-MM-DD and valid date
    def is_valid_date(s):
        if pd.isna(s):
            return False
        s = str(s).strip()
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', s):
            return False
        try:
            datetime.strptime(s, "%Y-%m-%d")
            return True
        except:
            return False

    r5_fail = ~r1_fail & ~r2_fail & ~r3_fail & ~r4_fail & ~raw["pay_date_txt"].apply(is_valid_date)
    for idx in raw[r5_fail].index:
        if idx in valid_indices:
            rejects.append({"row_num": raw.loc[idx, "row_num"], "reject_reason": "BAD_DATE"})
            valid_indices.discard(idx)

    # R6: DUPLICATE - keep only the row with lowest row_num per trimmed payment_id
    survivors = raw.loc[list(valid_indices)].copy()
    if len(survivors) > 0:
        survivors["trimmed_id"] = survivors["payment_id"].str.strip()
        # Find the minimum row_num for each trimmed payment_id
        min_row_per_id = survivors.groupby("trimmed_id", as_index=False)["row_num"].min()
        min_row_per_id.columns = ["trimmed_id", "min_row_num"]

        # Merge to identify duplicates
        survivors = survivors.merge(min_row_per_id, on="trimmed_id", how="left")
        duplicates = survivors[survivors["row_num"] != survivors["min_row_num"]]

        for idx in duplicates.index:
            rejects.append({"row_num": survivors.loc[idx, "row_num"], "reject_reason": "DUPLICATE"})

        # Keep only non-duplicates
        valid_survivors = survivors[survivors["row_num"] == survivors["min_row_num"]].copy()
    else:
        valid_survivors = survivors

    # Build valid_payments from survivors
    if len(valid_survivors) > 0:
        valid_df = pd.DataFrame()
        valid_df["payment_id"] = valid_survivors["payment_id"].str.strip()
        valid_df["account_id"] = valid_survivors["account_id"].astype("int64")
        valid_df["amount"] = valid_survivors["amount_txt"].apply(parse_amount).astype("float64")
        valid_df["currency"] = valid_survivors["currency"].str.strip().str.upper()
        valid_df["pay_date"] = valid_survivors["pay_date_txt"].str.strip()
    else:
        valid_df = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])
        valid_df["account_id"] = valid_df["account_id"].astype("int64")
        valid_df["amount"] = valid_df["amount"].astype("float64")

    # Build payment_rejects
    rejects_df = pd.DataFrame(rejects)
    if len(rejects_df) == 0:
        rejects_df = pd.DataFrame(columns=["row_num", "reject_reason"])
        rejects_df["row_num"] = rejects_df["row_num"].astype("int64")
    else:
        rejects_df["row_num"] = rejects_df["row_num"].astype("int64")

    return {
        "valid_payments": valid_df,
        "payment_rejects": rejects_df
    }
